function setup() {
	// pixelDensity(4);
	// mySize = 1000;
	mySize = max(windowWidth, windowHeight);
	createCanvas(mySize, mySize);
	// createCanvas(windowWidth, windowHeight);
	colorMode(HSB, 360, 100, 100, 100);
	palette = random(colorScheme).colors.concat();
	if (int(seed) % 2 == 0) {
		color_setup1 = random(colorScheme).colors.concat();
		color_setup2 = random(colorScheme).colors.concat();
	} else {
		color_setup1 = colors7;
		color_setup2 = colors8;
	}
	color_bg = "#000000";
	// color_setup1 = colors7;
	// color_setup2 = colors7
	// color_bg = "#fff";
	background(color_bg);
	angle_c = 0;
	branch = 4;
}

function draw() {

// [SENTINEL 專家 2 修復] 音訊座標數值防禦
if(typeof window.simulatedMouseX === 'number' && isNaN(window.simulatedMouseX)) window.simulatedMouseX = width*0.5;
if(typeof window.simulatedMouseY === 'number' && isNaN(window.simulatedMouseY)) window.simulatedMouseY = height*0.5;

	randomSeed(seed);
	drawingContext.shadowColor = str(random(color_setup1)) + "00";
	drawingContext.shadowOffsetX = 0;
	drawingContext.shadowOffsetY = 0;
	drawingContext.shadowBlur = 0;
	translate(width / 2, height / 2);
	rotate(angle_c);
	for (let i = 0; i < 1; i++) {
		colors[0] = random(color_setup2);
		colors[1] = random(color_setup2);
		colors[2] = random(color_setup2);
		colors[3] = random(color_setup1);
		colors[4] = random(color_setup2);
		circleForm(0, 0, mySize * 1.7 * (i + 1)/2);
	}

	if (frameCount % 5 == 0 && branch < 1200) {
		branch += 10;
		angle_c += TAU / 4;
	} else if (branch >= 1200) {
		branch += 0;
		angle_c += 0;
	}
	if (frameCount >= 1200) {
		seed = int(random(9821));
		background(color_bg);
		randomSeed(seed);
		frameCount = 0;
		branch = 4;
		angle_c = 0;
	}
}

function circleForm(x, y, d) {
	let ang = TAU / branch;
	let angles = [];
	for (let i = 0; i < branch; i++) {
		angles.push(ang * (i + iteration(0.1, 0.25)));
	}
	for (let i = 0; i < branch; i++) {
		let ang1 = angles[i];
		let ang2 = angles[(i + int(random(6))) % angles.length];
		let dd = d * iteration(0, 1);
		noFill();
		drawingContext.shadowColor = random(color_setup1);
		drawingContext.shadowOffsetX = random(-5, 5);
		drawingContext.shadowOffsetY = random(-5, 5);
		drawingContext.shadowBlur = 0;
		stroke(colors[random([0, 1, 2, 3, 4])]);
		strokeWeight(random(1));
		arc(x, y, dd, dd, ang1, ang2);
	}
}

function iteration(s, e) {
	let t = random(10, 100);
	let v = random(0.001, 0.01);
	return map(cos(t + frameCount * v), -1, 1, s, e);
}

function keyTyped() {
	if (key === "s" || key === "S") {
		saveCanvas("NoisePlanet_GAMMA", "png");
	}
}

